API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Auth_WAF_Component, "Authentication & WAF Component", "APIM Policies", "Handles security, WAF protection, rate-limiting, and authentication for incoming traffic.")
    Component(Routing_Configuration_Loader, "Routing Configuration Loader", "Azure App Configuration", "Fetches and stores version-controlled routing rules to support rapid one-day fallback.")
    Component(Transformation_Caching_Component, "Transformation & Caching Component", "APIM Liquid Templates / Response Cache", "Transforms request and response payloads and caches frequent queries.")
    Component(Circuit_Breaker_Policy_Engine, "Circuit Breaker Policy Engine", "APIM native policies", "Manages fallback routing and failure handling between the Azure service and legacy mainframe.")
}

Rel(Routing_Configuration_Loader, Auth_WAF_Component, "Supplies routing rules", "HTTPS")
Rel(Auth_WAF_Component, Transformation_Caching_Component, "Passes authenticated requests for transformation", "")
Rel(Transformation_Caching_Component, Circuit_Breaker_Policy_Engine, "Routes processed requests through circuit breaker policies", "")

@enduml

Integration/Sync Service & Read-Model Sy.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Integration_Sync_Service_Read_Model_Sync_Worker", "Integration/Sync Service & Read-Model Sync Worker") {
    Component("Inbound Event Router", "Inbound Event Router", ".NET 8 Isolated Worker", "Consumes messages from Azure Service Bus and coordinates processing.")
    Component("Read-Model Projection Engine", "Read-Model Projection Engine", ".NET 8", "Builds and updates read-models for fast adjuster user experiences.")
    Component("Legacy Sync Bridge & Mainframe Adapter", "Legacy Sync Bridge & Mainframe Adapter", ".NET 8 / Azure Container Apps", "Handles bi-directional state synchronization with the on-premise mainframe via IPSec VPN / Azure ExpressRoute.")
}

Rel("Inbound Event Router", "Read-Model Projection Engine", "Forwards processed event data for projection updates", "")
Rel("Legacy Sync Bridge & Mainframe Adapter", "Inbound Event Router", "Sends synchronized legacy state updates", "")

@enduml
